'use client';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useTheme } from 'next-themes';
import { useState, useEffect } from 'react';
import {
    LayoutDashboard,
    Zap,
    Brain,
    Sparkles,
    Network,
    BookOpen,
    Moon,
    Sun,
    LogOut,
    Menu,
    X,
    Share2,
    FlaskConical,
    Mic
} from 'lucide-react';
import { cn } from '@/lib/utils';

export function Navbar() {
    const pathname = usePathname();
    const { theme, setTheme } = useTheme();
    const [mounted, setMounted] = useState(false);
    const [handle, setHandle] = useState<string | null>(null);
    const [mobileOpen, setMobileOpen] = useState(false);

    useEffect(() => {
        setMounted(true);
        setHandle(localStorage.getItem('cp-handle'));

        const checkHandle = () => setHandle(localStorage.getItem('cp-handle'));
        window.addEventListener('storage', checkHandle);
        window.addEventListener('nav-update', checkHandle); // Custom event for same-tab updates
        return () => {
            window.removeEventListener('storage', checkHandle);
            window.removeEventListener('nav-update', checkHandle);
        };
    }, []);

    if (!mounted) return null;

    const navItems = [
        { name: 'Dashboard', href: '/dashboard', icon: LayoutDashboard },
        { name: 'Skills', href: '/skills', icon: Network },
        { name: 'Flashback', href: '/flashback', icon: Brain },
        { name: 'Dojo', href: '/senpai', icon: Sparkles },
        { name: 'Racer', href: '/racer', icon: Zap },
        { name: 'Studio', href: '/studio', icon: Network },
        { name: 'Interview', href: '/interview', icon: Mic },
        { name: 'Stress', href: '/stress', icon: Zap },
        { name: 'Blogs', href: '/blog-hunter', icon: BookOpen },
    ];

    const isActive = (path: string) => pathname === path;

    return (
        <nav className="sticky top-0 z-50 w-full border-b border-zinc-800 bg-background/80 backdrop-blur-xl supports-[backdrop-filter]:bg-background/60">
            <div className="max-w-7xl mx-auto px-4">
                <div className="flex h-16 items-center justify-between">
                    {/* Logo */}
                    <Link href="/dashboard" className="flex items-center gap-2 font-bold text-xl bg-gradient-to-r from-blue-500 to-cyan-500 bg-clip-text text-transparent">
                        CP-ZeroToHero
                    </Link>

                    {/* Desktop Nav */}
                    <div className="hidden md:flex items-center gap-1">
                        {navItems.map((item) => (
                            <Link
                                key={item.href}
                                href={item.href}
                                id={`nav-${item.name.toLowerCase().replace(' ', '-')}`}
                                className={cn(
                                    "flex items-center gap-2 px-3 py-2 rounded-md text-sm font-medium transition-colors",
                                    isActive(item.href)
                                        ? "bg-primary/10 text-primary"
                                        : "text-zinc-500 hover:text-foreground hover:bg-zinc-800/50"
                                )}
                            >
                                <item.icon size={16} />
                                {item.name}
                            </Link>
                        ))}
                    </div>

                    {/* Right Side: Theme & User */}
                    <div className="hidden md:flex items-center gap-4">
                        <button
                            onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
                            className="p-2 rounded-md hover:bg-zinc-800 transition text-zinc-500 hover:text-foreground"
                            aria-label="Toggle Theme"
                        >
                            {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
                        </button>

                        {handle ? (
                            <div className="flex items-center gap-3 pl-4 border-l border-zinc-800">
                                <span className="text-sm font-bold text-foreground">{handle}</span>
                                <button
                                    onClick={() => {
                                        localStorage.removeItem('cp-handle');
                                        window.dispatchEvent(new Event('nav-update'));
                                        window.location.reload();
                                    }}
                                    className="text-zinc-500 hover:text-red-500 transition"
                                    title="Logout"
                                >
                                    <LogOut size={16} />
                                </button>
                            </div>
                        ) : (
                            <Link href="/dashboard" className="text-sm text-primary hover:underline font-medium">
                                Login
                            </Link>
                        )}
                    </div>

                    {/* Mobile Menu Button */}
                    <div className="md:hidden flex items-center gap-2">
                        <button
                            onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
                            className="p-2 text-zinc-500"
                        >
                            {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
                        </button>
                        <button
                            onClick={() => setMobileOpen(!mobileOpen)}
                            className="p-2 text-zinc-500 hover:text-foreground"
                        >
                            {mobileOpen ? <X size={24} /> : <Menu size={24} />}
                        </button>
                    </div>
                </div>
            </div>

            {/* Mobile Nav */}
            {mobileOpen && (
                <div className="md:hidden border-t border-zinc-800 bg-background px-4 py-4 space-y-2">
                    {navItems.map((item) => (
                        <Link
                            key={item.href}
                            href={item.href}
                            onClick={() => setMobileOpen(false)}
                            className={cn(
                                "flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors",
                                isActive(item.href)
                                    ? "bg-primary/10 text-primary"
                                    : "text-zinc-500 hover:text-foreground hover:bg-zinc-800/50"
                            )}
                        >
                            <item.icon size={18} />
                            {item.name}
                        </Link>
                    ))}
                    {handle && (
                        <button
                            onClick={() => {
                                localStorage.removeItem('cp-handle');
                                window.location.reload();
                            }}
                            className="flex w-full items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium text-red-500 hover:bg-red-500/10 transition-colors"
                        >
                            <LogOut size={18} />
                            Logout ({handle})
                        </button>
                    )}
                </div>
            )}
        </nav>
    );
}
